 * @product D1
 * @category Storage & Databases
 */
export interface QueryDatabase extends Binding.Service<
  QueryDatabase,
  "Cloudflare.D1.QueryDatabase",
  (database: Database) => Effect.Effect<QueryDatabaseClient>
